"""Explicit anonymous export of completed Round1 evidence; no raw input or model payload."""
import sys,json,math,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.stvg_evidence_common_v1 import BASE,read,write,sha
OUT=ROOT/'results/stvg_evidence_constrained/2026-10-15'
def main():
 import matplotlib;matplotlib.use('Agg')
 import matplotlib.pyplot as plt
 OUT.mkdir(parents=True,exist_ok=True)
 b=BASE/'round1';raw=read(b/'POSTSEAL_ROWS.json')['rows'];rows=[dict(case_id=x['case_id'],dataset=x['dataset'],arm=x['arm'],metrics=x['metrics'])for x in raw];write(OUT/'ROUND1_ALL_ROWS.json',dict(status='complete',rows=rows,development=True,confirmation=False))
 summ=read(b/'POSTSEAL_SUMMARY.json');pairs=read(b/'PARENT_PAIRED_DELTAS.json');diag=read(b/'TEMPORAL_MECHANISM_DIAGNOSTICS.json')
 for name,value in [('ROUND1_SUMMARY.json',summ),('ROUND1_PARENT_PAIRS.json',pairs),('ROUND1_MECHANISM.json',diag),('ROUND1_ROOT.json',read(b/'ROOT_TEMPORAL_READBACK.json')),('TEMPORAL_SELECTION.json',read(BASE/'TEMPORAL_SELECTION_LOCK.json')),('DESIGN.json',read(BASE/'DESIGN_LOCK.json')),('PRESERVATION_RULE.json',read(BASE/'PRESERVATION_RULE_LOCK.json'))]:write(OUT/name,value)
 means={(r['dataset'],r['arm']):100*r['mean']for r in summ['summary']if r['metric']=='m_vIoU'}
 text=['# Evidence-constrained STVG: completed Round1, continuing matched spatial study','','Status: partial. Only the first temporal comparison is complete. Round2, new32 confirmation and official13785-query Table1 are not complete. This report does not promote CURRENT.','','## Controlled temporal comparison','','Same32 historically exposed development parents (16 per direction), frozen TA-STVG source features, original sealed Caption–Query feedback and fixed spatial references. All predictions were sealed before development GT scoring; there are no GT-derived references or GT Oracle fits. No Bootstrap.','','|Temporal arm|HC T-only vIoU (%)|Vid T-only vIoU (%)|HC T+fixed-S (%)|Vid T+fixed-S (%)|','|---|---:|---:|---:|---:|']
 for v in ['projection','original','stable','offset_trust']:text.append('|'+v+'|'+ '|'.join(f'{means[ds,p+v]:.6f}'for p,ds in [('T_','hc2'),('T_','vidstg'),('TS_','hc2'),('TS_','vidstg')])+'|')
 text+=['','Original is the old fixed five-step Adam. Stable fits the same averaged candidate KL+L2 with positive-step L-BFGS/Armijo. Offset-trust fits per-offset candidate KL plus full-grid KL(p0||p_theta), lambda1 and L2 .001, tau1, max50 accepted iterations. This is one locked comparison, not a temperature/learning-rate search.','','28 inputs were usable and4 explicitly fell back for unavailable temporal input. Original final objective decreased in9/28 fits; both revised objectives decreased in28/28 with nonzero parameter updates. Stable changed24 complete decoded intervals and offset-trust changed22. All28 offset-trust fits hit the50-iteration cap: monotonic descent is established, convergence is not. The independent NumPy reader verified6012 objective/grid-decode checks with max error below2.14e-15. These proxy losses do not establish that MLLM preferences are correct.','','The prelocked global equal-domain T+fixed-S endpoint selects offset_trust over stable. Development selection is disclosed; these scores are not an untouched test estimate. Projection and original remain reported controls.','','## Next bounded stages','','Round2 fixes temporal and spatial update parameters and compares old/new event clock × crop/full-scene IDs. Same-center cached proposals and masks are reused exactly; new centers use the unchanged SelectiveSearch256/GrabCut24/DIS, up to8new+Source mechanism. Full-scene and crop within each clock share candidate geometry and IDs. Original algorithms can be non-deterministic on fresh replay, so regenerated candidates are never silently called exact cache reuse.','','An old-cache replay mismatch stopped CPU preparation before new R1/Student/GT. The preserved old partial input and a separate engineering revision keep the original frozen sources unchanged. The student entry imports and temporal interval-to-seal bindings were checked before any new Student fit.','','Further32 sources exclude all64 previous coordinate parents and the route original8, plus enumerated old teacher/development registries; this is a recorded-registry exclusion, not a universal never-seen claim. Source capture is complete, adaptation/confirmation scoring has not run. The algorithm will freeze before confirmation, and confirmation cannot choose another recipe. Full official Table1 uses HC validation3482 + Vid test10303 queries, episodic F/T/S/TS with all predictions sealed before GT. Old Native YOLO/SAM queues remain stopped. No new detector, segmenter, DINO or CURRENT promotion.','','Only one prelocked output-preservation ablation is allowed if the chosen spatial arm meets the declared drift condition; no new algorithm or parameter grid follows. External teacher training overlap remains unresolved.','','All anonymous rows, including negative, neutral and null outcomes, are exported. Raw queries, frames, masks, coordinates, annotation files, weights and cached hidden tensors are excluded.']
 report='\n'.join(text)+'\n';(ROOT/'docs/STVG_EVIDENCE_CONSTRAINED_PROGRESS.md').write_text(report);(OUT/'REPORT.md').write_text(report)
 labels=['Projection','Original Adam','Stable KL','Offset trust'];fig,ax=plt.subplots(1,2,figsize=(11,4.3),constrained_layout=True)
 for a,ds,title in zip(ax,['hc2','vidstg'],['HC-STVG-v2','VidSTG']):
  values=[means[ds,'TS_'+v]for v in ['projection','original','stable','offset_trust']];a.bar(labels,values,color=['#7e8a9c','#ad7853','#66a096','#3e6d9d']);a.set_title(title+' / 16 development parents');a.set_ylabel('T + fixed S vIoU (%)');a.tick_params(axis='x',rotation=18);a.grid(axis='y',alpha=.15)
  for i,v in enumerate(values):a.text(i,v+.07,f'{v:.3f}',ha='center',fontsize=9)
 fig.savefig(OUT/'ROUND1.png',dpi=160);plt.close(fig)
 assert len(rows)==len(raw)
 for x,y in zip(rows,raw):assert x['metrics']==y['metrics']
 for x in summ['summary']:
  vals=[r['metrics'][x['metric']]for r in rows if r['dataset']==x['dataset']and r['arm']==x['arm']and r['metrics'][x['metric']]is not None];assert len(vals)==x['count'];assert (x['mean']is None and not vals)or abs(math.fsum(vals)/len(vals)-x['mean'])<1e-12
 write(BASE/'ROUND1_ANONYMOUS_SCALAR_AUDIT.json',dict(status='pass',row_count=len(rows),summary_scalar_count=len(summ['summary']),all_positive_negative_neutral_null_preserved=True,scope='completed Round1 only',CPU_only=True))
 print('round1 exported',len(rows),len(summ['summary']))
if __name__=='__main__':main()
